/* From Uiverse.io by Pradeepsaranbishnoi - Tags: radio */
.__UIV_SCOPE__ .radio-button {
  display: flex;
  gap: 10px;
  justify-content: center;
  margin: 10px;
  position: relative;
  align-items: center;
  color: white;
}

.__UIV_SCOPE__ .radio-button input[type="radio"] {
  position: absolute;
  opacity: 0;
}

.__UIV_SCOPE__ .radio {
  position: relative;
  display: inline-block;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid #ccc;
  box-shadow: 0px 0px 5px rgba(0, 0, 0, 0.2);
  transform: translateZ(-25px);
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .radio::before {
  position: absolute;
  content: '';
  width: 10px;
  height: 10px;
  top: 5px;
  left: 5px;
  border-radius: 50%;
  background-color: #fff;
  box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.5);
  opacity: 0;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .radio-button input[type="radio"]:checked + .radio {
  border-color: #5cb85c;
  transform: translateZ(0px);
  background-color: #fff;
}

.__UIV_SCOPE__ .radio-button input[type="radio"]:checked + .radio::before {
  opacity: 1;
}
